CREATE FUNCTION public.network_admin_message_count() RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admins only'; END IF; RETURN (SELECT count(*) FROM public.network_messages); END; $$; REVOKE ALL ON FUNCTION public.network_admin_message_count() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.network_admin_message_count() TO authenticated,service_role;